  "improvements": [
    {
      "kind": "equipment",
      "id": "blender",
      "decision": "improved existing draft",
      "added": "A processor can leave deliberately coarse pieces or use a disc to slice and shred. A blender is usually chosen for a flowing, smooth mixture. Overlapping puree tasks do not make the appliances equivalent; use the attachment and batch size the recipe actually needs.",
      "sources": [
        "b2-processors"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "equipment",
        "id": "food-processor"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "food-processor",
      "decision": "improved existing draft",
      "added": "A blade chops material already in the bowl, whereas a slicing disc cuts food as it enters. Choosing a disc instead of running the bowl blade changes the kind of result, not just its fineness. Blender recipes with plentiful liquid may need a different work-bowl limit.",
      "sources": [
        "b2-processors"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "equipment",
        "id": "blender"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "stand-mixer",
      "decision": "improved existing draft",
      "added": "Tilt-head and bowl-lift describe how the bowl and mixing head are accessed, not different culinary processes. Optional pasta rollers and grinders are separate attachments: having a stand mixer does not by itself provide those functions.",
      "sources": [
        "b2-mixers"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "steaming-basket",
      "decision": "improved existing draft",
      "added": "The basket supports food above the water while allowing steam through; a lid and suitable pan complete the cooking arrangement. A colander can drain food, but that alone does not establish that it fits a covered pan or is suitable for heating.",
      "sources": [
        "landolakes-equipment"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "equipment",
        "id": "colander"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "thermometer",
      "decision": "improved existing draft",
      "added": "The measurement location matters as much as the display. An appliance thermometer describes the surrounding cooking environment; a food probe describes the region around its sensing area. These readings answer different questions, so an oven reading does not replace a measurement within the food.",
      "sources": [
        "fsis-thermometers"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "USDA refetch returned 403; restricted to existing sourced project evidence."
    },
    {
      "kind": "equipment",
      "id": "pressure-cooker",
      "decision": "improved existing draft",
      "added": "A pressure-canner reference describes equipment and a validated jar-processing system. A pressure-cooker recipe describes cooking a meal. Similar pressure-related names do not transfer one system’s evidence to the other; choose the applicable documentation before treating them as substitutes.",
      "sources": [
        "b2-canners"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "equipment",
        "id": "pressure-canner"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "mandoline",
      "decision": "improved existing draft",
      "added": "Thin, repeated vegetable slices are useful in fermented-vegetable preparation as well as salads. Slicing and pounding have different jobs: a slicer sets piece shape, while pounding or massaging releases juice. A uniform cut alone does not establish fermentation conditions.",
      "sources": [
        "b2-ferment-tools"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "wok",
      "decision": "improved existing draft",
      "added": "Stir-fry ingredients are often added in stages because they need different cooking times. A wok provides space for that sequence, but the vessel name does not make a crowded mixture a stir-fry. Match the preparation and loading to the intended method.",
      "sources": [
        "cia-techniques"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "dutch-oven",
      "decision": "improved existing draft",
      "added": "The covered stage of a braise retains moisture; reducing its cooking liquid is a separate, evaporative step. A Dutch oven can participate in both, but keeping the same lid position throughout does not serve both purposes.",
      "sources": [
        "cia-techniques"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "equipment",
      "id": "cast-iron-frying-pan",
      "decision": "improved existing draft",
      "added": "Skillet describes the shallow cooking form; cast iron describes the material. A cast-iron Dutch oven is a deeper, lidded vessel. Shared material does not make their capacity, access for turning food or evaporation behaviour identical.",
      "sources": [
        "lodge-guide"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "equipment",
        "id": "dutch-oven"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "process",
      "id": "simmer",
      "decision": "improved existing draft",
      "added": "A simmer describes the liquid’s activity, while reduction describes losing liquid through evaporation. A covered simmer can cook food without the same reduction as an uncovered pan. State the desired consistency separately when a sauce must also concentrate.",
      "sources": [
        "cia-reduce"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "process",
      "id": "boil",
      "decision": "improved existing draft",
      "added": "Boiling food immerses it in hot liquid; steaming exposes it to vapour above liquid. These are different heat-transfer arrangements even when both begin with boiling water. A steamer basket therefore does not make its contents boiled food.",
      "sources": [
        "cia-moist-heat"
      ],
      "relationship": {
        "relation": "contrast-with",
        "kind": "process",
        "id": "steam"
      },
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "process",
      "id": "roast",
      "decision": "improved existing draft",
      "added": "Covering a roasting vessel changes how moisture escapes and introduces a trapped-steam environment. Browning an exposed surface and retaining moisture under a lid are different aims; a recipe may deliberately move between them.",
      "sources": [
        "cia-reduce"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
    },
    {
      "kind": "process",
      "id": "braise",
      "decision": "improved existing draft",
      "added": "A covered cooking stage and an uncovered sauce-finishing stage can belong to the same dish. Removing the lid encourages evaporation; this explains why the sauce may be reduced separately after the food is tender.",
      "sources": [
        "cia-reduce"
      ],
      "relationship": null,
      "review": "Draft / generated (0.1)",
      "uncertainties": "Editorial comparison; no universal operating limits inferred."
